// Phase 1: additive index. The default build is REPLICATED (every member builds
// concurrently) -- so watch per-secondary lag while it runs.
db.orders.createIndex({customer_id: 1, _id: 1}, {name: "idx_customer_id"});
db.currentOp({"command.createIndexes": {$exists: true}});
rs.printSecondaryReplicationInfo();   // NOT printReplicationInfo(): that is the oplog window

// Phase 2: batched backfill. No $gt cursor -- comparison operators type-bracket, so a
// keyset over _id strands every _id whose BSON type differs from the cursor's. The
// predicate selects each batch and is also the resume point.
while (true) {
  const batch = db.orders.find({status_v2: {$exists: false}}, {_id: 1})
                  .sort({_id: 1}).limit(5000).toArray();
  if (batch.length === 0) break;
  const ids = batch.map(d => d._id);
  db.orders.updateMany(
    {_id: {$in: ids}, status_v2: {$exists: false}},
    {$set: {status_v2: "active"}},
    {writeConcern: {w: "majority"}}
  );
  sleep(100);
}

// Phase 3: app deploy with dual-write.

// Phase 4: validator. moderate exempts ONLY updates to documents that already fail
// validation; inserts and updates to compliant documents are validated either way.
db.runCommand({collMod: "orders",
  validator: {$jsonSchema: {required: ["customer_id", "status_v2"]}},
  validationLevel: "moderate"});
db.orders.countDocuments({status_v2: {$exists: false}});   // must be 0 before strict
db.runCommand({collMod: "orders", validationLevel: "strict"});

